cat > /workspace/src/cli.rs <<'EOF'
//! Hand-rolled command-line parser producing output compatible with the
//! upstream binary that used `clap`.

use std::process::ExitCode;

use crate::commands::{BuildArgs, DevArgs, GenerateCiArgs, ServeArgs};

/// Derive a reasonable short program name from argv[0] for use in help and
/// error output.
pub fn binary_name(argv0: &str) -> String {
    let base = argv0.rsplit('/').next().unwrap_or(argv0);
    base.to_string()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OutputFormat {
    Human,
    Json,
}

impl OutputFormat {
    fn parse(s: &str) -> Option<Self> {
        match s {
            "human" => Some(OutputFormat::Human),
            "json" => Some(OutputFormat::Json),
            _ => None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CiKind {
    Github,
}

impl CiKind {
    fn parse(s: &str) -> Option<Self> {
        match s {
            "github" => Some(CiKind::Github),
            _ => None,
        }
    }
}

#[derive(Debug, Default, Clone)]
pub struct Globals {
    pub verbose: bool,
    pub output_format: OutputFormat,
}

impl Default for OutputFormat {
    fn default() -> Self {
        OutputFormat::Human
    }
}

pub enum Action {
    PrintAndExit(String),
    Build(Globals, BuildArgs),
    Dev(Globals, DevArgs),
    Serve(Globals, ServeArgs),
    GenerateCi(Globals, GenerateCiArgs),
}

impl Action {
    pub fn run(self) -> Result<(), ExitCode> {
        match self {
            Action::PrintAndExit(text) => {
                print!("{}", text);
                Ok(())
            }
            Action::Build(g, a) => crate::commands::build::run(g, a),
            Action::Dev(g, a) => crate::commands::dev::run(g, a),
            Action::Serve(g, a) => crate::commands::serve::run(g, a),
            Action::GenerateCi(g, a) => crate::commands::generate::run_ci(g, a),
        }
    }
}

pub struct CliError {
    /// The human readable error message
    message: String,
    /// Usage line content after "Usage:"
    usage: String,
    /// Extra tip line (appears with a blank line before it)
    tip: Option<String>,
    /// Extra information printed with brackets below the message
    bracket_info: Option<String>,
    /// Append "For more information, try '--help'." footer
    suggest_help: bool,
    /// Exit code to use
    exit_code: u8,
}

impl CliError {
    pub fn emit(&self, _bin: &str) {
        eprint!("{}", self.format());
    }

    fn format(&self) -> String {
        let mut out = String::new();
        out.push_str(&format!("error: {}", self.message));
        out.push('\n');
        if let Some(info) = &self.bracket_info {
            out.push_str(&format!("  [{}]\n", info));
        }
        if let Some(tip) = &self.tip {
            out.push('\n');
            out.push_str(&format!("  tip: {}\n", tip));
        }
        out.push('\n');
        out.push_str(&format!("Usage: {}\n", self.usage));
        if self.suggest_help {
            out.push('\n');
            out.push_str("For more information, try '--help'.\n");
        }
        out
    }

    pub fn exit_code(&self) -> u8 {
        self.exit_code
    }
}

fn err_unknown_subcommand(bin: &str, sub: &str, scope: UsageScope) -> CliError {
    CliError {
        message: format!("unrecognized subcommand '{}'", sub),
        usage: scope.usage(bin),
        tip: None,
        bracket_info: None,
        suggest_help: scope.suggest_help(),
        exit_code: 2,
    }
}

fn err_unknown_argument(bin: &str, arg: &str, scope: UsageScope, tip: Option<String>) -> CliError {
    let usage = if tip.is_some() {
        // when clap emits a "similar argument" tip, it sometimes changes the
        // usage line to point at the suggested flag only.
        let suggested_flag = extract_suggested_flag(tip.as_ref().unwrap());
        if let Some(flag) = suggested_flag {
            format!("{} {}", scope.base_usage(bin), flag)
        } else {
            scope.usage(bin)
        }
    } else {
        scope.usage(bin)
    };
    CliError {
        message: format!("unexpected argument '{}' found", arg),
        usage,
        tip,
        bracket_info: None,
        suggest_help: true,
        exit_code: 2,
    }
}

fn err_unknown_value(arg: &str, value: &str, scope: UsageScope, bin: &str) -> CliError {
    CliError {
        message: format!(
            "unexpected value '{}' for '{}' found; no more were expected",
            value, arg
        ),
        usage: format!("{} {}", scope.base_usage(bin), arg),
        tip: None,
        bracket_info: None,
        suggest_help: true,
        exit_code: 2,
    }
}

fn err_invalid_value(
    arg_display: &str,
    value: &str,
    possible: Option<&str>,
    reason: Option<&str>,
    scope: UsageScope,
    bin: &str,
) -> CliError {
    let message = if let Some(reason) = reason {
        format!("invalid value '{}' for '{}': {}", value, arg_display, reason)
    } else {
        format!("invalid value '{}' for '{}'", value, arg_display)
    };
    let _ = bin;
    let _ = scope;
    CliError {
        message,
        usage: scope.usage(bin),
        tip: None,
        bracket_info: possible.map(|p| format!("possible values: {}", p)),
        suggest_help: true,
        exit_code: 2,
    }
}

fn err_duplicate(arg_display: &str, scope: UsageScope, bin: &str) -> CliError {
    CliError {
        message: format!("the argument '{}' cannot be used multiple times", arg_display),
        usage: scope.usage(bin),
        tip: None,
        bracket_info: None,
        suggest_help: true,
        exit_code: 2,
    }
}

fn err_missing_value(arg_display: &str, possible: Option<&str>, scope: UsageScope, bin: &str) -> CliError {
    CliError {
        message: format!(
            "a value is required for '{}' but none was supplied",
            arg_display
        ),
        usage: scope.usage(bin),
        tip: None,
        bracket_info: possible.map(|p| format!("possible values: {}", p)),
        suggest_help: true,
        exit_code: 2,
    }
}

fn extract_suggested_flag(tip: &str) -> Option<String> {
    // tip looks like "a similar argument exists: '--verbose'"
    let first = tip.find('\'')?;
    let rest = &tip[first + 1..];
    let end = rest.find('\'')?;
    Some(rest[..end].to_string())
}

#[derive(Clone, Copy)]
pub enum UsageScope {
    Root,
    Build,
    Dev,
    Serve,
    Generate,
    GenerateCi,
    Help,
}

impl UsageScope {
    fn base_usage(self, bin: &str) -> String {
        match self {
            UsageScope::Root => format!("{} [OPTIONS] <COMMAND>", bin),
            UsageScope::Build => format!("{} build [OPTIONS]", bin),
            UsageScope::Dev => format!("{} dev [OPTIONS]", bin),
            UsageScope::Serve => format!("{} serve [OPTIONS]", bin),
            UsageScope::Generate => format!("{} generate [OPTIONS] <COMMAND>", bin),
            UsageScope::GenerateCi => format!("{} generate ci [OPTIONS]", bin),
            UsageScope::Help => format!("{} help [COMMAND]...", bin),
        }
    }

    fn usage(self, bin: &str) -> String {
        self.base_usage(bin)
    }

    fn suggest_help(self) -> bool {
        !matches!(self, UsageScope::Help)
    }
}

/// Suggest a similar option given a user-supplied flag, by finding the closest
/// match (by a simple prefix / Levenshtein score) among a list of knowns.
fn suggest_similar(user: &str, options: &[&str]) -> Option<String> {
    // Simple heuristic: prefer options that have a common prefix of length > 2,
    // otherwise the closest Levenshtein distance.
    let mut best: Option<(&&str, usize)> = None;
    for opt in options {
        let dist = edit_distance(user, opt);
        let score = dist;
        // Filter: ignore options that are far away relative to length.
        let max_len = user.len().max(opt.len());
        if score * 3 > max_len * 2 {
            continue;
        }
        if best.map_or(true, |(_, b)| score < b) {
            best = Some((opt, score));
        }
    }
    best.map(|(o, _)| (*o).to_string())
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur: Vec<usize> = vec![0; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

pub fn parse(bin: &str, args: &[String]) -> Result<Action, CliError> {
    let mut it = args.iter().peekable();
    let mut globals = Globals::default();
    let mut verbose_seen = false;
    let mut format_seen = false;

    // Top-level loop: consume global options / --help / --version until we
    // see a subcommand or run out.
    loop {
        let Some(raw) = it.peek().map(|s| s.as_str()) else {
            // No subcommand provided.
            let msg = main_short_help(bin);
            return Err(CliError {
                message: String::new(), // unused
                usage: String::new(),
                tip: None,
                bracket_info: None,
                suggest_help: false,
                exit_code: 2,
            })
            .map_err(|mut e| {
                e.exit_code = 2;
                e
            })
            .and_then(|_| -> Result<Action, CliError> { unreachable!() })
            .or_else(|_| -> Result<Action, CliError> {
                // Replace with a simpler action: print help to stdout and exit 2.
                Ok(Action::PrintAndExit(msg))
            });
        };
        match raw {
            "-h" => {
                it.next();
                return Ok(Action::PrintAndExit(main_short_help(bin)));
            }
            "--help" => {
                it.next();
                return Ok(Action::PrintAndExit(main_long_help(bin)));
            }
            "-V" | "--version" => {
                it.next();
                return Ok(Action::PrintAndExit(format!("oranda 0.6.5\n")));
            }
            "-v" | "--verbose" => {
                it.next();
                if verbose_seen {
                    return Err(err_duplicate("--verbose", UsageScope::Root, bin));
                }
                globals.verbose = true;
                verbose_seen = true;
            }
            "--output-format" => {
                it.next();
                if format_seen {
                    return Err(err_duplicate("--output-format <OUTPUT_FORMAT>", UsageScope::Root, bin));
                }
                format_seen = true;
                let Some(v) = it.next() else {
                    return Err(err_missing_value(
                        "--output-format <OUTPUT_FORMAT>",
                        Some("human, json"),
                        UsageScope::Root,
                        bin,
                    ));
                };
                let Some(fmt) = OutputFormat::parse(v) else {
                    return Err(err_invalid_value(
                        "--output-format <OUTPUT_FORMAT>",
                        v,
                        Some("human, json"),
                        None,
                        UsageScope::Root,
                        bin,
                    ));
                };
                globals.output_format = fmt;
            }
            s if s.starts_with("--output-format=") => {
                it.next();
                if format_seen {
                    return Err(err_duplicate("--output-format <OUTPUT_FORMAT>", UsageScope::Root, bin));
                }
                format_seen = true;
                let v = &s["--output-format=".len()..];
                let Some(fmt) = OutputFormat::parse(v) else {
                    return Err(err_invalid_value(
                        "--output-format <OUTPUT_FORMAT>",
                        v,
                        Some("human, json"),
                        None,
                        UsageScope::Root,
                        bin,
                    ));
                };
                globals.output_format = fmt;
            }
            "build" => {
                it.next();
                return parse_build(bin, &mut it, globals, verbose_seen, format_seen);
            }
            "dev" => {
                it.next();
                return parse_dev(bin, &mut it, globals, verbose_seen, format_seen);
            }
            "serve" => {
                it.next();
                return parse_serve(bin, &mut it, globals, verbose_seen, format_seen);
            }
            "generate" => {
                it.next();
                return parse_generate(bin, &mut it, globals, verbose_seen, format_seen);
            }
            "help" => {
                it.next();
                return parse_help(bin, &mut it);
            }
            sub if !sub.starts_with('-') => {
                return Err(err_unknown_subcommand(bin, sub, UsageScope::Root));
            }
            other => {
                let tip = suggest_similar(other, &["--verbose", "--output-format"])
                    .map(|s| format!("a similar argument exists: '{}'", s));
                return Err(err_unknown_argument(bin, other, UsageScope::Root, tip));
            }
        }
    }
}

fn consume_globals<I>(
    bin: &str,
    it: &mut std::iter::Peekable<I>,
    arg: &str,
    globals: &mut Globals,
    verbose_seen: &mut bool,
    format_seen: &mut bool,
    scope: UsageScope,
) -> Option<Result<(), CliError>>
where
    I: Iterator<Item = &'a String>,
{
    let _ = (bin, it, arg, globals, verbose_seen, format_seen, scope);
    None
}
EOF
