fn parse_generate(bin: &str, rest: &[String], mut state: GlobalState) -> Result<Action, CliError> {
    // `generate` has its own -o/-s options plus a required subcommand.
    let mut output_path: Option<String> = None;
    let mut site_path: Option<String> = None;
    let mut i = 0;
    while i < rest.len() {
        let a = rest[i].as_str();
        match a {
            "-h" => return Ok(Action::PrintStdout(help::generate_short(bin))),
            "--help" => return Ok(Action::PrintStdout(help::generate_long(bin))),
            "-v" | "--verbose" => {
                state.set_verbose(UsageScope::Generate, bin)?;
                i += 1;
            }
            "--output-format" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-format <OUTPUT_FORMAT>",
                        Some("human, json"),
                        UsageScope::Generate,
                        bin,
                    ));
                };
                state.set_output_format(v, UsageScope::Generate, bin)?;
                i += 2;
            }
            x if x.starts_with("--output-format=") => {
                state.set_output_format(
                    &x["--output-format=".len()..],
                    UsageScope::Generate,
                    bin,
                )?;
                i += 1;
            }
            "-o" | "--output-path" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-path <OUTPUT_PATH>",
                        None,
                        UsageScope::Generate,
                        bin,
                    ));
                };
                output_path = Some(v.clone());
                i += 2;
            }
            x if x.starts_with("--output-path=") => {
                output_path = Some(x["--output-path=".len()..].to_string());
                i += 1;
            }
            "-s" | "--site-path" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--site-path <SITE_PATH>",
                        None,
                        UsageScope::Generate,
                        bin,
                    ));
                };
                site_path = Some(v.clone());
                i += 2;
            }
            x if x.starts_with("--site-path=") => {
                site_path = Some(x["--site-path=".len()..].to_string());
                i += 1;
            }
            "ci" => {
                return parse_generate_ci(
                    bin,
                    &rest[i + 1..],
                    state,
                    output_path,
                    site_path,
                );
            }
            "help" => {
                return parse_generate_help(bin, &rest[i + 1..]);
            }
            sub if !sub.starts_with('-') => {
                return Err(err_unknown_subcommand(bin, sub, UsageScope::Generate));
