                }
                port_seen = true;
                s.port = parse_port(&a["--port=".len()..], UsageScope::Serve, bin)?;
                i += 1;
            }
            other if other.starts_with('-') => {
                let tip = suggest_similar(
                    other,
                    &["--verbose", "--output-format", "--port", "--help"],
                )
                .map(|s| format!("a similar argument exists: '{}'", s));
                return Err(err_unknown_argument(bin, other, UsageScope::Serve, tip));
            }
            other => {
                return Err(err_unknown_argument(bin, other, UsageScope::Serve, None));
            }
        }
    }
    Ok(Action::Serve(state.globals, s))
}

fn parse_generate(bin: &str, rest: &[String], mut state: GlobalState) -> Result<Action, CliError> {
    // `generate` has its own -o/-s options plus a required subcommand.
    let mut output_path: Option<String> = None;
    let mut site_path: Option<String> = None;
    let mut i = 0;
    while i < rest.len() {
        let a = rest[i].as_str();
        match a {
            "-h" => return Ok(Action::PrintStdout(help::generate_short(bin))),
            "--help" => return Ok(Action::PrintStdout(help::generate_long(bin))),
            "-v" | "--verbose" => {
                state.set_verbose(UsageScope::Generate, bin)?;
                i += 1;
            }
            "--output-format" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-format <OUTPUT_FORMAT>",
                        Some("human, json"),
                        UsageScope::Generate,
                        bin,
                    ));
                };
                state.set_output_format(v, UsageScope::Generate, bin)?;
                i += 2;
            }
            x if x.starts_with("--output-format=") => {
                state.set_output_format(
                    &x["--output-format=".len()..],
                    UsageScope::Generate,
                    bin,
                )?;
                i += 1;
            }
            "-o" | "--output-path" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-path <OUTPUT_PATH>",
                        None,
                        UsageScope::Generate,
                        bin,
                    ));
                };
                output_path = Some(v.clone());
                i += 2;
            }
            x if x.starts_with("--output-path=") => {
                output_path = Some(x["--output-path=".len()..].to_string());
                i += 1;
            }
            "-s" | "--site-path" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--site-path <SITE_PATH>",
                        None,
                        UsageScope::Generate,
                        bin,
                    ));
                };
                site_path = Some(v.clone());
                i += 2;
            }
            x if x.starts_with("--site-path=") => {
                site_path = Some(x["--site-path=".len()..].to_string());
                i += 1;
            }
            "ci" => {
                return parse_generate_ci(
                    bin,
                    &rest[i + 1..],
                    state,
                    output_path,
                    site_path,
                );
            }
            "help" => {
                return parse_generate_help(bin, &rest[i + 1..]);
            }
            sub if !sub.starts_with('-') => {
                return Err(err_unknown_subcommand(bin, sub, UsageScope::Generate));
            }
            other => {
                let tip = suggest_similar(
                    other,
                    &[
                        "--verbose",
                        "--output-format",
                        "--output-path",
                        "--site-path",
                        "--help",
                    ],
                )
                .map(|s| format!("a similar argument exists: '{}'", s));
                return Err(err_unknown_argument(bin, other, UsageScope::Generate, tip));
            }
        }
    }
    // No subcommand: print short help, exit 2.
    Err(CliError {
        message: String::new(),
        usage: String::new(),
        tip: None,
        bracket_info: None,
        suggest_help: false,
        exit_code: 2,
        override_body: Some(help::generate_short(bin)),
    })
}

fn parse_generate_ci(
    bin: &str,
    rest: &[String],
    mut state: GlobalState,
    mut output_path: Option<String>,
    mut site_path: Option<String>,
) -> Result<Action, CliError> {
    let mut ci_kind = CiKind::Github;
    let mut ci_seen = false;
    let mut i = 0;
    while i < rest.len() {
        let a = rest[i].as_str();
        match a {
            "-h" => return Ok(Action::PrintStdout(help::generate_ci_short(bin))),
            "--help" => return Ok(Action::PrintStdout(help::generate_ci_long(bin))),
            "-v" | "--verbose" => {
                state.set_verbose(UsageScope::GenerateCi, bin)?;
                i += 1;
            }
            "--output-format" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-format <OUTPUT_FORMAT>",
                        Some("human, json"),
                        UsageScope::GenerateCi,
                        bin,
                    ));
                };
                state.set_output_format(v, UsageScope::GenerateCi, bin)?;
                i += 2;
            }
            x if x.starts_with("--output-format=") => {
                state.set_output_format(
                    &x["--output-format=".len()..],
                    UsageScope::GenerateCi,
                    bin,
                )?;
                i += 1;
            }
            "-o" | "--output-path" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-path <OUTPUT_PATH>",
                        None,
                        UsageScope::GenerateCi,
                        bin,
                    ));
                };
                output_path = Some(v.clone());
                i += 2;
            }
            x if x.starts_with("--output-path=") => {
                output_path = Some(x["--output-path=".len()..].to_string());
                i += 1;
            }
            "-s" | "--site-path" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--site-path <SITE_PATH>",
                        None,
                        UsageScope::GenerateCi,
                        bin,
                    ));
                };
                site_path = Some(v.clone());
                i += 2;
            }
            x if x.starts_with("--site-path=") => {
                site_path = Some(x["--site-path=".len()..].to_string());
                i += 1;
            }
            "--ci" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--ci <CI>",
                        Some("github"),
                        UsageScope::GenerateCi,
                        bin,
                    ));
                };
                if ci_seen {
                    return Err(err_duplicate("--ci <CI>", UsageScope::GenerateCi, bin));
                }
                ci_seen = true;
                let Some(c) = CiKind::parse(v) else {
                    return Err(err_invalid_value(
                        "--ci <CI>",
                        v,
                        Some("github"),
                        None,
                        UsageScope::GenerateCi,
                        bin,
                    ));
                };
                ci_kind = c;
                i += 2;
            }
            x if x.starts_with("--ci=") => {
                let v = &x["--ci=".len()..];
                if ci_seen {
                    return Err(err_duplicate("--ci <CI>", UsageScope::GenerateCi, bin));
                }
                ci_seen = true;
                let Some(c) = CiKind::parse(v) else {
                    return Err(err_invalid_value(
                        "--ci <CI>",
                        v,
                        Some("github"),
                        None,
                        UsageScope::GenerateCi,
                        bin,
                    ));
                };
                ci_kind = c;
                i += 1;
            }
            other if other.starts_with('-') => {
                let tip = suggest_similar(
                    other,
                    &[
                        "--verbose",
                        "--output-format",
                        "--output-path",
                        "--site-path",
                        "--ci",
                        "--help",
                    ],
                )
                .map(|s| format!("a similar argument exists: '{}'", s));
                return Err(err_unknown_argument(bin, other, UsageScope::GenerateCi, tip));
            }
            other => {
                return Err(err_unknown_argument(bin, other, UsageScope::GenerateCi, None));
            }
        }
    }
    let _ = ci_kind;
    Ok(Action::GenerateCi(
        state.globals,
        GenerateCiArgs {
            output_path,
            site_path,
            ci: ci_kind,
        },
    ))
}

fn parse_help(bin: &str, rest: &[String]) -> Result<Action, CliError> {
    // `help` followed by a chain of subcommands. Unknown ones are reported.
    if rest.is_empty() {
        return Ok(Action::PrintStdout(help::main_long(bin)));
    }
    // Walk the chain.
    let mut cur: &str = "";
    let mut path: Vec<&str> = Vec::new();
    for arg in rest {
        let s = arg.as_str();
        let allowed: &[&str] = match cur {
            "" => &["build", "dev", "serve", "generate", "help"],
            "generate" => &["ci", "help"],
            _ => &[],
        };
        if !allowed.contains(&s) {
            // Emit unknown subcommand error with "Usage: <bin> help [COMMAND]..."
            return Err(CliError {
                message: format!("unrecognized subcommand '{}'", s),
                usage: format!("{} help [COMMAND]...", bin),
                tip: None,
                bracket_info: None,
                suggest_help: false,
                exit_code: 2,
                override_body: None,
            });
        }
        path.push(s);
        cur = s;
    }
    match path.as_slice() {
        ["build"] => Ok(Action::PrintStdout(help::build_long(bin))),
        ["dev"] => Ok(Action::PrintStdout(help::dev_long(bin))),
        ["serve"] => Ok(Action::PrintStdout(help::serve_long(bin))),
        ["generate"] => Ok(Action::PrintStdout(help::generate_long(bin))),
        ["generate", "ci"] => Ok(Action::PrintStdout(help::generate_ci_long(bin))),
        ["generate", "help"] => Ok(Action::PrintStdout(help::help_help(bin, Some("generate")))),
        ["help"] => Ok(Action::PrintStdout(help::help_help(bin, None))),
        _ => Ok(Action::PrintStdout(help::main_long(bin))),
    }
}

fn parse_generate_help(bin: &str, rest: &[String]) -> Result<Action, CliError> {
    // generate help [subcommand]
    if rest.is_empty() {
        return Ok(Action::PrintStdout(help::generate_long(bin)));
    }
    let s = rest[0].as_str();
    match s {
        "ci" => Ok(Action::PrintStdout(help::generate_ci_long(bin))),
        "help" => Ok(Action::PrintStdout(help::help_help(bin, Some("generate")))),
        _ => Err(CliError {
            message: format!("unrecognized subcommand '{}'", s),
            usage: format!("{} generate help [COMMAND]...", bin),
            tip: None,
            bracket_info: None,
            suggest_help: false,
            exit_code: 2,
            override_body: None,
        }),
    }
}

fn parse_port(v: &str, scope: UsageScope, bin: &str) -> Result<u16, CliError> {
    // Clap's u16 parser uses the Rust `str::parse` and then emits
    // messages like "invalid digit found in string" or
    // "N is not in 0..=65535".
    match v.parse::<u16>() {
        Ok(n) => Ok(n),
        Err(_) => {
            // Distinguish between bad digit and out of range.
            let reason = if v.parse::<i128>().is_ok() {
                format!("{} is not in 0..=65535", v)
            } else if v.parse::<f64>().is_ok() && !v.chars().all(|c| c.is_ascii_digit() || c == '-' || c == '+') {
                "invalid digit found in string".to_string()
            } else {
                "invalid digit found in string".to_string()
            };
            Err(err_invalid_value(
                "--port <PORT>",
                v,
                None,
                Some(&reason),
                scope,
                bin,
            ))
        }
    }
}

