//! Hand-rolled command-line parser producing output compatible with the
//! upstream binary that used `clap`.

use std::process::ExitCode;

use crate::commands::{BuildArgs, DevArgs, GenerateCiArgs, ServeArgs};

/// Derive a reasonable short program name from argv[0] for use in help and
/// error output.
pub fn binary_name(argv0: &str) -> String {
    let base = argv0.rsplit('/').next().unwrap_or(argv0);
    base.to_string()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OutputFormat {
    Human,
    Json,
}

impl OutputFormat {
    fn parse(s: &str) -> Option<Self> {
        match s {
            "human" => Some(OutputFormat::Human),
            "json" => Some(OutputFormat::Json),
            _ => None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CiKind {
    Github,
}

impl CiKind {
    fn parse(s: &str) -> Option<Self> {
        match s {
            "github" => Some(CiKind::Github),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Globals {
    pub verbose: bool,
    pub output_format: OutputFormat,
}

impl Default for Globals {
    fn default() -> Self {
        Self {
            verbose: false,
            output_format: OutputFormat::Human,
        }
    }
}

pub enum Action {
    PrintStdout(String),
    Build(Globals, BuildArgs),
    Dev(Globals, DevArgs),
    Serve(Globals, ServeArgs),
    GenerateCi(Globals, GenerateCiArgs),
}

impl Action {
    pub fn run(self) -> Result<(), ExitCode> {
        match self {
            Action::PrintStdout(text) => {
                print!("{}", text);
                Ok(())
            }
            Action::Build(g, a) => crate::commands::build::run(g, a),
            Action::Dev(g, a) => crate::commands::dev::run(g, a),
            Action::Serve(g, a) => crate::commands::serve::run(g, a),
            Action::GenerateCi(g, a) => crate::commands::generate::run_ci(g, a),
        }
    }
}

#[derive(Clone, Copy)]
pub enum UsageScope {
    Root,
    Build,
    Dev,
    Serve,
    Generate,
    GenerateCi,
    Help,
}

impl UsageScope {
    fn base_usage(self, bin: &str) -> String {
        match self {
            UsageScope::Root => format!("{} [OPTIONS] <COMMAND>", bin),
            UsageScope::Build => format!("{} build [OPTIONS]", bin),
            UsageScope::Dev => format!("{} dev [OPTIONS]", bin),
            UsageScope::Serve => format!("{} serve [OPTIONS]", bin),
            UsageScope::Generate => format!("{} generate [OPTIONS] <COMMAND>", bin),
            UsageScope::GenerateCi => format!("{} generate ci [OPTIONS]", bin),
            UsageScope::Help => format!("{} help [COMMAND]...", bin),
        }
    }

    fn usage(self, bin: &str) -> String {
        self.base_usage(bin)
    }

    fn suggest_help(self) -> bool {
        !matches!(self, UsageScope::Help)
    }
}

pub struct CliError {
    message: String,
    usage: String,
    tip: Option<String>,
    bracket_info: Option<String>,
    suggest_help: bool,
    exit_code: u8,
    /// If set, the whole "error: " body (and prior formatting) is
    /// replaced with this pre-baked text.
    override_body: Option<String>,
}

impl CliError {
    pub fn emit(&self, _bin: &str) {
        eprint!("{}", self.format());
    }

    fn format(&self) -> String {
        if let Some(body) = &self.override_body {
            return body.clone();
        }
        let mut out = String::new();
        out.push_str(&format!("error: {}\n", self.message));
        if let Some(info) = &self.bracket_info {
            out.push_str(&format!("  [{}]\n", info));
        }
        if let Some(tip) = &self.tip {
            out.push('\n');
            out.push_str(&format!("  tip: {}\n", tip));
        }
        out.push('\n');
        out.push_str(&format!("Usage: {}\n", self.usage));
        if self.suggest_help {
            out.push('\n');
            out.push_str("For more information, try '--help'.\n");
        }
        out
    }

    pub fn exit_code(&self) -> u8 {
        self.exit_code
    }
}

fn err_unknown_subcommand(bin: &str, sub: &str, scope: UsageScope) -> CliError {
    CliError {
        message: format!("unrecognized subcommand '{}'", sub),
        usage: scope.usage(bin),
        tip: None,
        bracket_info: None,
        suggest_help: scope.suggest_help(),
        exit_code: 2,
        override_body: None,
    }
}

fn err_unknown_argument(bin: &str, arg: &str, scope: UsageScope, tip: Option<String>) -> CliError {
    let usage = if let Some(t) = &tip {
        let flag = extract_suggested_flag(t);
        match flag {
            Some(f) => match scope {
                UsageScope::Root => format!("{} {}", bin, f),
                UsageScope::Build => format!("{} build {}", bin, f),
                UsageScope::Dev => format!("{} dev {}", bin, f),
                UsageScope::Serve => format!("{} serve {}", bin, f),
                UsageScope::Generate => format!("{} generate {}", bin, f),
                UsageScope::GenerateCi => format!("{} generate ci {}", bin, f),
                UsageScope::Help => scope.usage(bin),
            },
            None => scope.usage(bin),
        }
    } else {
        scope.usage(bin)
    };
    CliError {
        message: format!("unexpected argument '{}' found", arg),
        usage,
        tip,
        bracket_info: None,
        suggest_help: true,
        exit_code: 2,
        override_body: None,
    }
}

fn err_unknown_value(arg: &str, value: &str, scope: UsageScope, bin: &str) -> CliError {
    CliError {
        message: format!(
            "unexpected value '{}' for '{}' found; no more were expected",
            value, arg
        ),
        usage: format!("{} {}", scope.base_usage_no_options(bin), arg),
        tip: None,
        bracket_info: None,
        suggest_help: true,
        exit_code: 2,
        override_body: None,
    }
}

fn err_invalid_value(
    arg_display: &str,
    value: &str,
    possible: Option<&str>,
    reason: Option<&str>,
    scope: UsageScope,
    bin: &str,
) -> CliError {
    let message = if let Some(reason) = reason {
        format!("invalid value '{}' for '{}': {}", value, arg_display, reason)
    } else {
        format!("invalid value '{}' for '{}'", value, arg_display)
    };
    CliError {
        message,
        usage: scope.usage(bin),
        tip: None,
        bracket_info: possible.map(|p| format!("possible values: {}", p)),
        suggest_help: true,
        exit_code: 2,
        override_body: None,
    }
}

fn err_duplicate(arg_display: &str, scope: UsageScope, bin: &str) -> CliError {
    CliError {
        message: format!("the argument '{}' cannot be used multiple times", arg_display),
        usage: scope.usage(bin),
        tip: None,
        bracket_info: None,
        suggest_help: true,
        exit_code: 2,
        override_body: None,
    }
}

fn err_missing_value(
    arg_display: &str,
    possible: Option<&str>,
    scope: UsageScope,
    bin: &str,
) -> CliError {
    CliError {
        message: format!(
            "a value is required for '{}' but none was supplied",
            arg_display
        ),
        usage: scope.usage(bin),
        tip: None,
        bracket_info: possible.map(|p| format!("possible values: {}", p)),
        suggest_help: true,
        exit_code: 2,
        override_body: None,
    }
}

fn extract_suggested_flag(tip: &str) -> Option<String> {
    // tip looks like "a similar argument exists: '--verbose'"
    let first = tip.find('\'')?;
    let rest = &tip[first + 1..];
    let end = rest.find('\'')?;
    Some(rest[..end].to_string())
}

impl UsageScope {
    fn base_usage_no_options(self, bin: &str) -> String {
        match self {
            UsageScope::Root => format!("{}", bin),
            UsageScope::Build => format!("{} build", bin),
            UsageScope::Dev => format!("{} dev", bin),
            UsageScope::Serve => format!("{} serve", bin),
            UsageScope::Generate => format!("{} generate", bin),
            UsageScope::GenerateCi => format!("{} generate ci", bin),
            UsageScope::Help => format!("{} help", bin),
        }
    }
}

fn suggest_similar(user: &str, options: &[&str]) -> Option<String> {
    let mut best: Option<(&&str, usize)> = None;
    for opt in options {
        let dist = edit_distance(user, opt);
        let max_len = user.len().max(opt.len());
        if dist * 3 > max_len * 2 {
            continue;
        }
        if best.map_or(true, |(_, b)| dist < b) {
            best = Some((opt, dist));
        }
    }
    best.map(|(o, _)| (*o).to_string())
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur: Vec<usize> = vec![0; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

/// Simple state tracking as we walk argv. Global options may appear anywhere;
/// the rest depends on the scope.
struct GlobalState {
    globals: Globals,
    verbose_seen: bool,
    format_seen: bool,
}

impl GlobalState {
    fn new() -> Self {
        Self {
            globals: Globals::default(),
            verbose_seen: false,
            format_seen: false,
        }
    }

    fn set_verbose(&mut self, scope: UsageScope, bin: &str) -> Result<(), CliError> {
        if self.verbose_seen {
            return Err(err_duplicate("--verbose", scope, bin));
        }
        self.verbose_seen = true;
        self.globals.verbose = true;
        Ok(())
    }

    fn set_output_format(&mut self, v: &str, scope: UsageScope, bin: &str) -> Result<(), CliError> {
        if self.format_seen {
            return Err(err_duplicate(
                "--output-format <OUTPUT_FORMAT>",
                scope,
                bin,
            ));
        }
        self.format_seen = true;
        match OutputFormat::parse(v) {
            Some(fmt) => {
                self.globals.output_format = fmt;
                Ok(())
            }
            None => Err(err_invalid_value(
                "--output-format <OUTPUT_FORMAT>",
                v,
                Some("human, json"),
                None,
                scope,
                bin,
            )),
        }
    }
}

pub fn parse(bin: &str, args: &[String]) -> Result<Action, CliError> {
    let mut state = GlobalState::new();
    let mut i = 0;
    while i < args.len() {
        let raw = args[i].as_str();
        match raw {
            "-h" => return Ok(Action::PrintStdout(help::main_short(bin))),
            "--help" => return Ok(Action::PrintStdout(help::main_long(bin))),
            "-V" | "--version" => return Ok(Action::PrintStdout(String::from("oranda 0.6.5\n"))),
            "-v" | "--verbose" => {
                state.set_verbose(UsageScope::Root, bin)?;
                i += 1;
            }
            "--output-format" => {
                let Some(v) = args.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-format <OUTPUT_FORMAT>",
                        Some("human, json"),
                        UsageScope::Root,
                        bin,
                    ));
                };
                state.set_output_format(v, UsageScope::Root, bin)?;
                i += 2;
            }
            s if s.starts_with("--output-format=") => {
                let v = &s["--output-format=".len()..];
                state.set_output_format(v, UsageScope::Root, bin)?;
                i += 1;
            }
            "build" => {
                return parse_build(bin, &args[i + 1..], state);
            }
            "dev" => {
                return parse_dev(bin, &args[i + 1..], state);
            }
            "serve" => {
                return parse_serve(bin, &args[i + 1..], state);
            }
            "generate" => {
                return parse_generate(bin, &args[i + 1..], state);
            }
            "help" => {
                return parse_help(bin, &args[i + 1..]);
            }
            sub if !sub.starts_with('-') => {
                return Err(err_unknown_subcommand(bin, sub, UsageScope::Root));
            }
            other => {
                let tip = suggest_similar(other, &["--verbose", "--output-format"])
                    .map(|s| format!("a similar argument exists: '{}'", s));
                return Err(err_unknown_argument(bin, other, UsageScope::Root, tip));
            }
        }
    }
    // No subcommand
    Err(CliError {
        message: String::new(),
        usage: String::new(),
        tip: None,
        bracket_info: None,
        suggest_help: false,
        exit_code: 2,
        override_body: Some(help::main_short(bin)),
    })
}

fn parse_build(bin: &str, rest: &[String], mut state: GlobalState) -> Result<Action, CliError> {
    let mut json_only_seen = false;
    let mut b = BuildArgs::default();
    let mut i = 0;
    while i < rest.len() {
        let a = rest[i].as_str();
        match a {
            "-h" => return Ok(Action::PrintStdout(help::build_short(bin))),
            "--help" => return Ok(Action::PrintStdout(help::build_long(bin))),
            "-v" | "--verbose" => {
                state.set_verbose(UsageScope::Build, bin)?;
                i += 1;
            }
            "--output-format" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-format <OUTPUT_FORMAT>",
                        Some("human, json"),
                        UsageScope::Build,
                        bin,
                    ));
                };
                state.set_output_format(v, UsageScope::Build, bin)?;
                i += 2;
            }
            s if s.starts_with("--output-format=") => {
                state.set_output_format(&s["--output-format=".len()..], UsageScope::Build, bin)?;
                i += 1;
            }
            "--json-only" => {
                if json_only_seen {
                    return Err(err_duplicate("--json-only", UsageScope::Build, bin));
                }
                json_only_seen = true;
                b.json_only = true;
                i += 1;
            }
            s if s.starts_with("--json-only=") => {
                let v = &s["--json-only=".len()..];
                return Err(err_unknown_value("--json-only", v, UsageScope::Build, bin));
            }
            other if other.starts_with('-') => {
                let tip = suggest_similar(other, &["--verbose", "--output-format", "--json-only", "--help"])
                    .map(|s| format!("a similar argument exists: '{}'", s));
                return Err(err_unknown_argument(bin, other, UsageScope::Build, tip));
            }
            other => {
                return Err(err_unknown_argument(bin, other, UsageScope::Build, None));
            }
        }
    }
    Ok(Action::Build(state.globals, b))
}

fn parse_dev(bin: &str, rest: &[String], mut state: GlobalState) -> Result<Action, CliError> {
