                if no_first_seen {
                    return Err(err_duplicate("--no-first-build", UsageScope::Dev, bin));
                }
                no_first_seen = true;
                d.no_first_build = true;
                i += 1;
            }
            "-i" | "--include-paths" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--include-paths <INCLUDE_PATHS>",
                        None,
                        UsageScope::Dev,
                        bin,
                    ));
                };
                for part in v.split(',') {
                    if !part.is_empty() {
                        d.include_paths.push(part.to_string());
                    }
                }
                i += 2;
            }
            s if s.starts_with("--include-paths=") => {
                let v = &s["--include-paths=".len()..];
                for part in v.split(',') {
                    if !part.is_empty() {
                        d.include_paths.push(part.to_string());
                    }
                }
                i += 1;
            }
            other if other.starts_with('-') => {
                let tip = suggest_similar(
                    other,
