fn parse_help(bin: &str, rest: &[String]) -> Result<Action, CliError> {
    // `help` followed by a chain of subcommands. Unknown ones are reported.
    if rest.is_empty() {
        return Ok(Action::PrintStdout(help::main_long(bin)));
    }
    // Walk the chain.
    let mut cur: &str = "";
    let mut path: Vec<&str> = Vec::new();
    for arg in rest {
        let s = arg.as_str();
        let allowed: &[&str] = match cur {
            "" => &["build", "dev", "serve", "generate", "help"],
            "generate" => &["ci", "help"],
            _ => &[],
        };
        if !allowed.contains(&s) {
            // Emit unknown subcommand error with "Usage: <bin> help [COMMAND]..."
            return Err(CliError {
                message: format!("unrecognized subcommand '{}'", s),
                usage: format!("{} help [COMMAND]...", bin),
                tip: None,
                bracket_info: None,
                suggest_help: false,
                exit_code: 2,
                override_body: None,
            });
        }
        path.push(s);
        cur = s;
    }
    match path.as_slice() {
        ["build"] => Ok(Action::PrintStdout(help::build_long(bin))),
        ["dev"] => Ok(Action::PrintStdout(help::dev_long(bin))),
        ["serve"] => Ok(Action::PrintStdout(help::serve_long(bin))),
        ["generate"] => Ok(Action::PrintStdout(help::generate_long(bin))),
        ["generate", "ci"] => Ok(Action::PrintStdout(help::generate_ci_long(bin))),
        ["generate", "help"] => Ok(Action::PrintStdout(help::help_help(bin, Some("generate")))),
        ["help"] => Ok(Action::PrintStdout(help::help_help(bin, None))),
        _ => Ok(Action::PrintStdout(help::main_long(bin))),
    }
}

fn parse_generate_help(bin: &str, rest: &[String]) -> Result<Action, CliError> {
    // generate help [subcommand]
    if rest.is_empty() {
        return Ok(Action::PrintStdout(help::generate_long(bin)));
    }
    let s = rest[0].as_str();
    match s {
        "ci" => Ok(Action::PrintStdout(help::generate_ci_long(bin))),
        "help" => Ok(Action::PrintStdout(help::help_help(bin, Some("generate")))),
        _ => Err(CliError {
            message: format!("unrecognized subcommand '{}'", s),
            usage: format!("{} generate help [COMMAND]...", bin),
            tip: None,
            bracket_info: None,
            suggest_help: false,
            exit_code: 2,
            override_body: None,
        }),
    }
}

fn parse_port(v: &str, scope: UsageScope, bin: &str) -> Result<u16, CliError> {
    // Clap's u16 parser uses the Rust `str::parse` and then emits
    // messages like "invalid digit found in string" or
    // "N is not in 0..=65535".
    match v.parse::<u16>() {
        Ok(n) => Ok(n),
        Err(_) => {
            // Distinguish between bad digit and out of range.
            let reason = if v.parse::<i128>().is_ok() {
                format!("{} is not in 0..=65535", v)
            } else if v.parse::<f64>().is_ok() && !v.chars().all(|c| c.is_ascii_digit() || c == '-' || c == '+') {
                "invalid digit found in string".to_string()
            } else {
                "invalid digit found in string".to_string()
            };
            Err(err_invalid_value(
                "--port <PORT>",
                v,
                None,
                Some(&reason),
                scope,
                bin,
            ))
        }
    }
}

