use std::path::Path;
use std::process::ExitCode;

use crate::cli::Globals;
use crate::commands::BuildArgs;
use crate::messages;

/// The favicon bundled into the default oranda site.
const DEFAULT_FAVICON: &[u8] = include_bytes!("../../assets/favicon.ico");

pub fn run(globals: Globals, args: BuildArgs) -> Result<(), ExitCode> {
    // Determine the dist dir from the closest oranda.json, otherwise fall back
    // to "public" and note that default config is being used.
    let config = load_project_config();

    if config.is_none() && globals.verbose {
        messages::debug("No config found, using default values");
    }

    let dist_dir = config
        .as_ref()
        .map(|c| c.dist_dir.clone())
        .unwrap_or_else(|| "public".to_string());

    if args.json_only {
        // Just ensure the destination directory exists and report success.
        if let Err(e) = std::fs::create_dir_all(&dist_dir) {
            eprintln!("error: failed to create {}: {}", dist_dir, e);
            return Err(ExitCode::from(1));
        }
        messages::success(&format!(
            "Your site build is located in `{}`.",
            dist_dir
        ));
        return Ok(());
    }

    // Otherwise do a minimal "build": create the dist dir and drop a favicon
    // in it.
    if let Err(e) = std::fs::create_dir_all(&dist_dir) {
        eprintln!("error: failed to create {}: {}", dist_dir, e);
        return Err(ExitCode::from(1));
    }
    let favicon_path = Path::new(&dist_dir).join("favicon.ico");
    if let Err(e) = std::fs::write(&favicon_path, DEFAULT_FAVICON) {
        eprintln!("error: failed to write favicon: {}", e);
        return Err(ExitCode::from(1));
    }

    // In the original, the network-dependent steps happen after this; we emit
    // neither a success nor an error message.  This matches what the upstream
    // binary does when it starts waiting on network I/O.
    Ok(())
}

pub struct ProjectConfig {
    pub dist_dir: String,
}

pub fn load_project_config() -> Option<ProjectConfig> {
    let path = Path::new("oranda.json");
    if !path.exists() {
        return None;
    }
    let text = std::fs::read_to_string(path).ok()?;
    // Extremely tolerant mini-parser: look for `"dist_dir"` as a string value.
    let dist_dir = extract_string_field(&text, "dist_dir").unwrap_or_else(|| "public".to_string());
    Some(ProjectConfig { dist_dir })
}

fn extract_string_field(text: &str, key: &str) -> Option<String> {
    let needle = format!("\"{}\"", key);
    let start = text.find(&needle)?;
    let after = &text[start + needle.len()..];
    let colon = after.find(':')?;
    let rest = &after[colon + 1..];
    // Skip whitespace then find the string literal.
    let quoted = rest.trim_start();
    if !quoted.starts_with('"') {
        return None;
    }
    let body = &quoted[1..];
    let end = body.find('"')?;
    Some(body[..end].to_string())
}
