use std::process::ExitCode;

use crate::cli::Globals;
use crate::commands::DevArgs;
use crate::messages;

pub fn run(_globals: Globals, args: DevArgs) -> Result<(), ExitCode> {
    // Figure out how many "paths to watch" we have.  The upstream tool
    // counts README.md if present, oranda.json if present, etc.  We
    // approximate: count README.md + oranda.json if present, plus
    // any explicit --include-paths entries.
    let mut count = 0usize;
    if std::path::Path::new("oranda.json").exists() {
        count += 1;
    }
    if std::path::Path::new("README.md").exists() {
        count += 1;
    }
    count += args.include_paths.len();
    if count == 0 {
        // Fall back to at least one: the config file location.
        count = 1;
    }
    messages::info(&format!("Found {} paths to watch, starting watch...", count));

    let port = args.port.unwrap_or(7979);

    // Start a simple static file server for the `public` directory.
    let dist_dir = "public";
    if !std::path::Path::new(dist_dir).exists() && !args.no_first_build {
        // Would build here, but build requires network; this matches
        // the panic behaviour of the original.
    }

    messages::success(&format!(
        "Your project is available at: http://127.0.0.1:{}",
        port
    ));

    if !std::path::Path::new(dist_dir).is_dir() {
        // Mimic the upstream panic when public/ cannot be found after a
        // no-first-build.
        eprintln!("  × oranda panicked.");
        eprintln!("  ├─▶ at src/commands/dev.rs:131:62");
        eprintln!("  ╰─▶ called `Result::unwrap()` on an `Err` value: BuildNotFound {{ dist_dir: \"public\" }}");
        eprintln!("  help: set the `RUST_BACKTRACE=1` environment variable to display a backtrace.");
        eprintln!();
        return Err(ExitCode::from(255));
    }

    match crate::http::serve(dist_dir, port) {
        Ok(()) => Ok(()),
        Err(e) => {
            eprintln!("error: {}", e);
            Err(ExitCode::from(1))
        }
    }
}
