cat > /workspace/src/commands/generate.rs <<'EOF'
use std::io::{self, BufRead, IsTerminal, Write};
use std::process::ExitCode;

use crate::cli::Globals;
use crate::commands::GenerateCiArgs;
use crate::messages;

pub fn run_ci(_globals: Globals, args: GenerateCiArgs) -> Result<(), ExitCode> {
    messages::info("Generating a CI deploy workflow for your site...");

    // Require a TTY to prompt; replicate upstream's panic message.
    if !io::stdin().is_terminal() {
        eprintln!("  × oranda panicked.");
        eprintln!("  ├─▶ at src/generate.rs:56:14");
        eprintln!("  ╰─▶ Error while prompting!: NotTTY");
        eprintln!("  help: set the `RUST_BACKTRACE=1` environment variable to display a backtrace.");
        eprintln!();
        return Err(ExitCode::from(255));
    }

    // Prompts:
    // 1) include hyperlink checker? default yes
    // 2) always use latest oranda version? default no
    // 3) append to .gitignore? default no
    let with_hyperlink = prompt_bool(
        "Do you want to include a tool for checking generated hyperlinks?",
        true,
        Some("Read more about the link checker tool: https://github.com/untitaker/hyperlink"),
    );
    let use_latest = prompt_bool(
        "Do you want to always use the latest version of oranda?",
        false,
        Some("Using the latest version means you don't have to rerun this command when oranda updates, but it may also break your site if you use a lot of configuration!"),
    );
    let append_gitignore = prompt_bool(
        "Would you like to append the default destination directory (`public`) to your .gitignore file?",
        false,
        None,
    );

    let output_path = args
        .output_path
        .clone()
        .unwrap_or_else(|| ".github/workflows/web.yml".to_string());

    if std::path::Path::new(&output_path).exists() {
        let overwrite = prompt_bool(
            &format!(
                "There's already a file at {:?}! Do you want to override it?",
                output_path
            ),
            false,
            None,
        );
        if !overwrite {
            messages::info("Ok, exiting...");
            return Ok(());
        }
    }

    if let Some(parent) = std::path::Path::new(&output_path).parent() {
        if !parent.as_os_str().is_empty() {
            if let Err(e) = std::fs::create_dir_all(parent) {
                eprintln!("error: failed to create {}: {}", parent.display(), e);
                return Err(ExitCode::from(1));
            }
        }
    }

    let content = render_ci(with_hyperlink, use_latest);
    if let Err(e) = std::fs::write(&output_path, content) {
        eprintln!("error: failed to write {}: {}", output_path, e);
        return Err(ExitCode::from(1));
    }

    if append_gitignore {
        let gi_path = std::path::Path::new(".gitignore");
        let existing = std::fs::read_to_string(gi_path).unwrap_or_default();
        let mut content = existing;
        if !content.is_empty() && !content.ends_with('\n') {
            content.push('\n');
        }
        content.push_str("\n# Generated by `oranda generate ci`\npublic/");
        if let Err(e) = std::fs::write(gi_path, content) {
            eprintln!("error: failed to write .gitignore: {}", e);
            return Err(ExitCode::from(1));
        }
    }

    messages::success(&format!("Wrote CI file to {:?}", output_path));
    Ok(())
}

fn prompt_bool(question: &str, default_yes: bool, hint: Option<&str>) -> bool {
    let suffix = if default_yes { "(Y/n)" } else { "(y/N)" };
    print!("? >o_o< {} {} ", question, suffix);
    if let Some(h) = hint {
        print!("\n[{}]", h);
    }
    let _ = io::stdout().flush();
    let mut line = String::new();
    let _ = io::stdin().lock().read_line(&mut line);
    let s = line.trim();
    if s.is_empty() {
        default_yes
    } else {
        matches!(s.chars().next(), Some('y') | Some('Y'))
    }
}

fn render_ci(with_hyperlink: bool, use_latest: bool) -> String {
    let install = if use_latest {
        "curl --proto '=https' --tlsv1.2 -LsSf https://github.com/axodotdev/oranda/releases/latest/download/oranda-installer.sh | sh"
    } else {
        "curl --proto '=https' --tlsv1.2 -LsSf https://github.com/axodotdev/oranda/releases/download/v0.6.1/oranda-installer.sh | sh"
    };
    let hyperlink_block = if with_hyperlink {
        r#"
      - name: Prepare HTML for link checking
        # untitaker/hyperlink supports no site prefixes, move entire site into
        # a subfolder
        run: mkdir /tmp/public/ && cp -R public /tmp/public/oranda

      - name: Check HTML for broken internal links
        uses: untitaker/hyperlink@0.1.29
        with:
          args: /tmp/public/
      "#
    } else {
        ""
    };
    format!(
r#"# Workflow to build your docs with oranda (and mdbook)
# and deploy them to Github Pages
name: Web

# We're going to push to the gh-pages branch, so we need that permission
permissions:
  contents: write

# What situations do we want to build docs in?
# All of these work independently and can be removed / commented out
# if you don't want oranda/mdbook running in that situation
on:
  # Check that a PR didn't break docs!
  #
  # Note that the "Deploy to Github Pages" step won't run in this mode,
  # so this won't have any side-effects. But it will tell you if a PR
  # completely broke oranda/mdbook. Sadly we don't provide previews (yet)!
  pull_request:

  # Whenever something gets pushed to main, update the docs!
  # This is great for getting docs changes live without cutting a full release.
  #
  # Note that if you're using cargo-dist, this will "race" the Release workflow
  # that actually builds the Github Release that oranda tries to read (and
  # this will almost certainly complete first). As a result you will publish
  # docs for the latest commit but the oranda landing page won't know about
  # the latest release. The workflow_run trigger below will properly wait for
  # cargo-dist, and so this half-published state will only last for ~10 minutes.
  #
  # If you only want docs to update with releases, disable this, or change it to
  # a "release" branch. You can, of course, also manually trigger a workflow run
  # when you want the docs to update.
  push:
    branches:
      - main

  # Whenever a workflow called "Release" completes, update the docs!
  #
  # If you're using cargo-dist, this is recommended, as it will ensure that
  # oranda always sees the latest release right when it's available. Note
  # however that Github's UI is wonky when you use workflow_run, and won't
  # show this workflow as part of any commit. You have to go to the "actions"
  # tab for your repo to see this one running (the gh-pages deploy will also
  # only show up there).
  workflow_run:
    workflows: [ "Release" ]
    types:
      - completed

# Alright, let's do it!
jobs:
  web:
    name: Build and deploy site and docs
    runs-on: ubuntu-latest
    steps:
      # Setup
      - uses: actions/checkout@v3
        with:
          fetch-depth: 0
      - uses: dtolnay/rust-toolchain@stable
      - uses: swatinem/rust-cache@v2

      # If you use any mdbook plugins, here's the place to install them!

      # Install and run oranda (and mdbook)!
      #
      # This will write all output to ./public/ (including copying mdbook's output to there).
      - name: Install and run oranda
        run: |
          {install}
          oranda build
      {hyperlink_block}
      # Deploy to our gh-pages branch (creating it if it doesn't exist).
      # The "public" dir that oranda made above will become the root dir
      # of this branch.
      #
      # Note that once the gh-pages branch exists, you must
      # go into repo's settings > pages and set "deploy from branch: gh-pages".
      # The other defaults work fine.
      - name: Deploy to Github Pages
        uses: JamesIves/github-pages-deploy-action@v4.4.1
        # ONLY if we're on main (so no PRs or feature branches allowed!)
        if: ${{ github.ref == 'refs/heads/main' }}
        with:
          branch: gh-pages
          # Gotta tell the action where to find oranda's output
          folder: public
          token: ${{ secrets.GITHUB_TOKEN }}
          single-commit: true"#,
        install = install,
        hyperlink_block = hyperlink_block
    )
}
EOF
