cat > /workspace/src/http.rs <<'EOF'
//! Tiny static file server.  Supports GET only, 200/404/405 responses.

use std::io::{self, BufRead, BufReader, Read, Write};
use std::net::{Ipv4Addr, TcpListener, TcpStream};
use std::path::{Component, Path, PathBuf};
use std::thread;
use std::time::SystemTime;

pub fn serve(root: &str, port: u16) -> io::Result<()> {
    let listener = TcpListener::bind((Ipv4Addr::new(127, 0, 0, 1), port))?;
    let root = PathBuf::from(root);
    for stream in listener.incoming() {
        let stream = stream?;
        let root = root.clone();
        thread::spawn(move || {
            let _ = handle(stream, &root);
        });
    }
    Ok(())
}

fn handle(stream: TcpStream, root: &Path) -> io::Result<()> {
    let peer = stream.peer_addr().ok();
    let _ = peer;
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut request_line = String::new();
    if reader.read_line(&mut request_line)? == 0 {
        return Ok(());
    }
    // Parse headers up to the blank line.
    loop {
        let mut line = String::new();
        let n = reader.read_line(&mut line)?;
        if n == 0 || line == "\r\n" || line == "\n" {
            break;
        }
    }

    let mut parts = request_line.trim_end().split_whitespace();
    let method = parts.next().unwrap_or("");
    let path = parts.next().unwrap_or("/");
    let _version = parts.next().unwrap_or("HTTP/1.1");

    let mut stream = stream;
    if method != "GET" && method != "HEAD" {
        send_status(&mut stream, 405, "Method Not Allowed", &[], None)?;
        return Ok(());
    }

    // Strip query fragment.
    let path = path.split('?').next().unwrap_or(path);

    // Resolve relative to root, rejecting '..' escapes.
    let mut full = root.to_path_buf();
    for comp in Path::new(path.trim_start_matches('/')).components() {
        match comp {
            Component::Normal(p) => full.push(p),
            Component::CurDir => {}
            _ => {
                send_status(&mut stream, 400, "Bad Request", &[], None)?;
                return Ok(());
            }
        }
    }

    if full.is_dir() {
        let index = full.join("index.html");
        if index.is_file() {
            full = index;
        } else {
            send_status(&mut stream, 404, "Not Found", &[], None)?;
            return Ok(());
        }
    }

    let data = match std::fs::read(&full) {
        Ok(d) => d,
        Err(_) => {
            send_status(&mut stream, 404, "Not Found", &[], None)?;
            return Ok(());
        }
    };
    let ct = content_type(&full);
    let modified = std::fs::metadata(&full)
        .ok()
        .and_then(|m| m.modified().ok())
        .map(http_date)
        .unwrap_or_else(http_date_now);

    let headers = vec![
        format!("content-type: {}", ct),
        "accept-ranges: bytes".to_string(),
        format!("last-modified: {}", modified),
    ];
    let body = if method == "HEAD" { None } else { Some(&data[..]) };
    send_status(&mut stream, 200, "OK", &headers, body)?;
    Ok(())
}

fn send_status(
    stream: &mut TcpStream,
    code: u16,
    reason: &str,
    extra_headers: &[String],
    body: Option<&[u8]>,
) -> io::Result<()> {
    let mut out = Vec::new();
    out.extend_from_slice(format!("HTTP/1.1 {} {}\r\n", code, reason).as_bytes());
    for h in extra_headers {
        out.extend_from_slice(h.as_bytes());
        out.extend_from_slice(b"\r\n");
    }
    let content_length = body.map(|b| b.len()).unwrap_or(0);
