        out.push_str(&format!("  tip: {}\n", t));
        let flag = extract_suggested_flag(t);
        match flag {
            Some(f) => format!("{} {}", scope.prefix(bin), f),
            None => scope.base_usage(bin),
        }
    } else {
        scope.base_usage(bin)
    };
    out.push('\n');
    out.push_str(&format!("Usage: {}\n", usage));
    out.push('\n');
    out.push_str("For more information, try '--help'.\n");
    e(out)
}

fn err_unknown_value(arg: &str, value: &str, scope: UsageScope, bin: &str) -> CliError {
