        ));
    }
    if let Some(p) = possible {
        out.push_str(&format!("  [possible values: {}]\n", p));
    }
    out.push('\n');
    out.push_str("For more information, try '--help'.\n");
    e(out)
}

fn err_duplicate(arg_display: &str, scope: UsageScope, bin: &str) -> CliError {
    e(format!(
        "error: the argument '{}' cannot be used multiple times\n\nUsage: {}\n\nFor more information, try '--help'.\n",
