fn parse_generate_ci(
    bin: &str,
    rest: &[String],
    mut state: GlobalState,
    mut output_path: Option<String>,
    mut site_path: Option<String>,
) -> Result<Action, CliError> {
    let mut ci_kind = CiKind::Github;
    let mut ci_seen = false;
    let mut i = 0;
    while i < rest.len() {
        let a = rest[i].as_str();
        match a {
            "-h" => return Ok(Action::PrintStdout(help::generate_ci_short(bin))),
            "--help" => return Ok(Action::PrintStdout(help::generate_ci_long(bin))),
            "-v" | "--verbose" => {
                state.set_verbose(UsageScope::GenerateCi, bin)?;
                i += 1;
            }
            "--output-format" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-format <OUTPUT_FORMAT>",
                        Some("human, json"),
                    ));
                };
                state.set_output_format(v, UsageScope::GenerateCi, bin)?;
                i += 2;
            }
            x if x.starts_with("--output-format=") => {
                state.set_output_format(
                    &x["--output-format=".len()..],
                    UsageScope::GenerateCi,
                    bin,
                )?;
                i += 1;
            }
            "-o" | "--output-path" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value("--output-path <OUTPUT_PATH>", None));
                };
                output_path = Some(v.clone());
                i += 2;
            }
            x if x.starts_with("--output-path=") => {
                output_path = Some(x["--output-path=".len()..].to_string());
                i += 1;
            }
            "-s" | "--site-path" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value("--site-path <SITE_PATH>", None));
                };
                site_path = Some(v.clone());
                i += 2;
            }
            x if x.starts_with("--site-path=") => {
                site_path = Some(x["--site-path=".len()..].to_string());
                i += 1;
            }
            "--ci" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value("--ci <CI>", Some("github")));
                };
                if ci_seen {
                    return Err(err_duplicate("--ci <CI>", UsageScope::GenerateCi, bin));
                }
                ci_seen = true;
                let Some(c) = CiKind::parse(v) else {
                    return Err(err_invalid_value(
                        "--ci <CI>",
                        v,
                        Some("github"),
                        None,
                    ));
                };
                ci_kind = c;
                i += 2;
            }
            x if x.starts_with("--ci=") => {
                let v = &x["--ci=".len()..];
                if ci_seen {
                    return Err(err_duplicate("--ci <CI>", UsageScope::GenerateCi, bin));
                }
                ci_seen = true;
                let Some(c) = CiKind::parse(v) else {
                    return Err(err_invalid_value(
                        "--ci <CI>",
                        v,
                        Some("github"),
                        None,
                    ));
                };
                ci_kind = c;
                i += 1;
            }
            other if other.starts_with('-') => {
                let tip = suggest_similar(other, suggestion_options(UsageScope::GenerateCi))
                    .map(|s| format!("a similar argument exists: '{}'", s));
                return Err(err_unknown_argument(bin, other, UsageScope::GenerateCi, tip));
            }
            other => {
                return Err(err_unknown_argument(bin, other, UsageScope::GenerateCi, None));
            }
        }
    }
    Ok(Action::GenerateCi(
        state.globals,
        GenerateCiArgs {
            output_path,
            site_path,
            ci: ci_kind,
        },
    ))
}

fn parse_help(bin: &str, rest: &[String]) -> Result<Action, CliError> {
    if rest.is_empty() {
        return Ok(Action::PrintStdout(help::main_long(bin)));
    }
    // Walk the chain.
    let mut cur: &str = "";
    let mut path: Vec<&str> = Vec::new();
    for arg in rest {
        let s = arg.as_str();
        let allowed: &[&str] = match cur {
            "" => &["build", "dev", "serve", "generate", "help"],
            "generate" => &["ci", "help"],
            _ => &[],
        };
        if !allowed.contains(&s) {
            // Match upstream: root usage + "For more information" footer.
            return Err(err_unknown_subcommand(bin, s, UsageScope::Root));
        }
        path.push(s);
        cur = s;
    }
    match path.as_slice() {
        ["build"] => Ok(Action::PrintStdout(help::build_long(bin))),
        ["dev"] => Ok(Action::PrintStdout(help::dev_long(bin))),
        ["serve"] => Ok(Action::PrintStdout(help::serve_long(bin))),
        ["generate"] => Ok(Action::PrintStdout(help::generate_long(bin))),
        ["generate", "ci"] => Ok(Action::PrintStdout(help::generate_ci_long(bin))),
        ["generate", "help"] => Ok(Action::PrintStdout(help::help_help(bin, Some("generate")))),
        ["help"] => Ok(Action::PrintStdout(help::help_help(bin, None))),
        _ => Ok(Action::PrintStdout(help::main_long(bin))),
    }
}

fn parse_generate_help(bin: &str, rest: &[String]) -> Result<Action, CliError> {
    if rest.is_empty() {
        return Ok(Action::PrintStdout(help::generate_long(bin)));
    }
    let s = rest[0].as_str();
    match s {
        "ci" => Ok(Action::PrintStdout(help::generate_ci_long(bin))),
        "help" => Ok(Action::PrintStdout(help::help_help(bin, Some("generate")))),
        _ => Err(err_unknown_subcommand(bin, s, UsageScope::Generate)),
    }
}

fn parse_port(v: &str) -> Result<u16, CliError> {
    match v.parse::<u16>() {
        Ok(n) => Ok(n),
        Err(_) => {
            let reason: String = if let Ok(_n) = v.parse::<u128>() {
                format!("{} is not in 0..=65535", v)
            } else if let Ok(_n) = v.parse::<i128>() {
                format!("{} is not in 0..=65535", v)
            } else {
                "invalid digit found in string".to_string()
            };
            Err(err_invalid_value("--port <PORT>", v, None, Some(&reason)))
        }
    }
}

