            }
            "--output-format" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-format <OUTPUT_FORMAT>",
                        Some("human, json"),
                    ));
                };
                state.set_output_format(v, UsageScope::Serve, bin)?;
                i += 2;
            }
            a if a.starts_with("--output-format=") => {
                state.set_output_format(&a["--output-format=".len()..], UsageScope::Serve, bin)?;
                i += 1;
            }
            "--port" => {
                let Some(v) = rest.get(i + 1) else {
                    return Err(err_missing_value("--port <PORT>", None));
                };
                if port_seen {
                    return Err(err_duplicate("--port <PORT>", UsageScope::Serve, bin));
                }
                port_seen = true;
                s.port = parse_port(v)?;
                i += 2;
            }
            a if a.starts_with("--port=") => {
                if port_seen {
                    return Err(err_duplicate("--port <PORT>", UsageScope::Serve, bin));
                }
                port_seen = true;
                s.port = parse_port(&a["--port=".len()..])?;
                i += 1;
            }
            other if other.starts_with('-') => {
                let tip = suggest_similar(other, suggestion_options(UsageScope::Serve))
                    .map(|s| format!("a similar argument exists: '{}'", s));
                return Err(err_unknown_argument(bin, other, UsageScope::Serve, tip));
            }
            other => {
                return Err(err_unknown_argument(bin, other, UsageScope::Serve, None));
            }
        }
    }
    Ok(Action::Serve(state.globals, s))
}

fn parse_generate(bin: &str, rest: &[String], mut state: GlobalState) -> Result<Action, CliError> {
    let mut output_path: Option<String> = None;
