//! Hand-rolled command-line parser producing output compatible with the
//! upstream binary that used `clap`.

use std::process::ExitCode;

use crate::commands::{BuildArgs, DevArgs, GenerateCiArgs, ServeArgs};

pub fn binary_name(argv0: &str) -> String {
    let base = argv0.rsplit('/').next().unwrap_or(argv0);
    base.to_string()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OutputFormat {
    Human,
    Json,
}

impl OutputFormat {
    fn parse(s: &str) -> Option<Self> {
        match s {
            "human" => Some(OutputFormat::Human),
            "json" => Some(OutputFormat::Json),
            _ => None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CiKind {
    Github,
}

impl CiKind {
    fn parse(s: &str) -> Option<Self> {
        match s {
            "github" => Some(CiKind::Github),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Globals {
    pub verbose: bool,
    pub output_format: OutputFormat,
}

impl Default for Globals {
    fn default() -> Self {
        Self {
            verbose: false,
            output_format: OutputFormat::Human,
        }
    }
}

pub enum Action {
    PrintStdout(String),
    Build(Globals, BuildArgs),
    Dev(Globals, DevArgs),
    Serve(Globals, ServeArgs),
    GenerateCi(Globals, GenerateCiArgs),
}

impl Action {
    pub fn run(self) -> Result<(), ExitCode> {
        match self {
            Action::PrintStdout(text) => {
                print!("{}", text);
                Ok(())
            }
            Action::Build(g, a) => crate::commands::build::run(g, a),
            Action::Dev(g, a) => crate::commands::dev::run(g, a),
            Action::Serve(g, a) => crate::commands::serve::run(g, a),
            Action::GenerateCi(g, a) => crate::commands::generate::run_ci(g, a),
        }
    }
}

#[derive(Clone, Copy)]
pub enum UsageScope {
    Root,
    Build,
    Dev,
    Serve,
    Generate,
    GenerateCi,
}

impl UsageScope {
    fn base_usage(self, bin: &str) -> String {
        match self {
            UsageScope::Root => format!("{} [OPTIONS] <COMMAND>", bin),
            UsageScope::Build => format!("{} build [OPTIONS]", bin),
            UsageScope::Dev => format!("{} dev [OPTIONS]", bin),
            UsageScope::Serve => format!("{} serve [OPTIONS]", bin),
            UsageScope::Generate => format!("{} generate [OPTIONS] <COMMAND>", bin),
            UsageScope::GenerateCi => format!("{} generate ci [OPTIONS]", bin),
        }
    }

    fn prefix(self, bin: &str) -> String {
        match self {
            UsageScope::Root => bin.to_string(),
            UsageScope::Build => format!("{} build", bin),
            UsageScope::Dev => format!("{} dev", bin),
            UsageScope::Serve => format!("{} serve", bin),
            UsageScope::Generate => format!("{} generate", bin),
            UsageScope::GenerateCi => format!("{} generate ci", bin),
        }
    }
}

pub struct CliError {
    body: String,
    exit_code: u8,
}

impl CliError {
    pub fn emit(&self, _bin: &str) {
        eprint!("{}", self.body);
    }

    pub fn exit_code(&self) -> u8 {
        self.exit_code
    }

    fn print_only(body: String, exit_code: u8) -> Self {
        Self { body, exit_code }
    }
}

fn e(body: String) -> CliError {
    CliError { body, exit_code: 2 }
}

fn err_unknown_subcommand(bin: &str, sub: &str, scope: UsageScope) -> CliError {
    e(format!(
        "error: unrecognized subcommand '{}'\n\nUsage: {}\n\nFor more information, try '--help'.\n",
        sub,
        scope.base_usage(bin)
    ))
}

fn err_unknown_argument(bin: &str, arg: &str, scope: UsageScope, tip: Option<String>) -> CliError {
    let mut out = format!("error: unexpected argument '{}' found\n", arg);
    let usage = if let Some(t) = &tip {
        out.push('\n');
        out.push_str(&format!("  tip: {}\n", t));
        let flag = extract_suggested_flag(t);
        match flag {
            Some(f) => format!("{} {}", scope.prefix(bin), f),
            None => scope.base_usage(bin),
        }
    } else {
        scope.base_usage(bin)
    };
    out.push('\n');
    out.push_str(&format!("Usage: {}\n", usage));
    out.push('\n');
    out.push_str("For more information, try '--help'.\n");
    e(out)
}

fn err_unknown_value(arg: &str, value: &str, scope: UsageScope, bin: &str) -> CliError {
    e(format!(
        "error: unexpected value '{}' for '{}' found; no more were expected\n\nUsage: {} {}\n\nFor more information, try '--help'.\n",
        value,
        arg,
        scope.prefix(bin),
        arg
    ))
}

fn err_invalid_value(
    arg_display: &str,
    value: &str,
    possible: Option<&str>,
    reason: Option<&str>,
) -> CliError {
    let mut out = String::new();
    if let Some(reason) = reason {
        out.push_str(&format!(
            "error: invalid value '{}' for '{}': {}\n",
            value, arg_display, reason
        ));
    } else {
        out.push_str(&format!(
            "error: invalid value '{}' for '{}'\n",
            value, arg_display
        ));
    }
    if let Some(p) = possible {
        out.push_str(&format!("  [possible values: {}]\n", p));
    }
    out.push('\n');
    out.push_str("For more information, try '--help'.\n");
    e(out)
}

fn err_duplicate(arg_display: &str, scope: UsageScope, bin: &str) -> CliError {
    e(format!(
        "error: the argument '{}' cannot be used multiple times\n\nUsage: {}\n\nFor more information, try '--help'.\n",
        arg_display,
        scope.base_usage(bin)
    ))
}

fn err_missing_value(
    arg_display: &str,
    possible: Option<&str>,
) -> CliError {
    let mut out = format!(
        "error: a value is required for '{}' but none was supplied\n",
        arg_display
    );
    if let Some(p) = possible {
        out.push_str(&format!("  [possible values: {}]\n", p));
    }
    out.push('\n');
    out.push_str("For more information, try '--help'.\n");
    e(out)
}

fn extract_suggested_flag(tip: &str) -> Option<String> {
    let first = tip.find('\'')?;
    let rest = &tip[first + 1..];
    let end = rest.find('\'')?;
    Some(rest[..end].to_string())
}

/// Suggest a similar flag using a conservative prefix/edit-distance rule.
fn suggest_similar(user: &str, options: &[&str]) -> Option<String> {
    let user_stripped = user.trim_start_matches('-');
    if user_stripped.is_empty() {
        return None;
    }
    let mut best: Option<(&&str, usize)> = None;
    for opt in options {
        let opt_stripped = opt.trim_start_matches('-');
        let score: Option<usize> = if opt_stripped.starts_with(user_stripped) && user_stripped.len() >= 2 {
            Some(0)
        } else if user_stripped.starts_with(opt_stripped) && opt_stripped.len() >= 3 {
            Some(1)
        } else {
            let d = edit_distance(user_stripped, opt_stripped);
            if d <= 2 {
                Some(2 + d)
            } else {
                None
            }
        };
        if let Some(s) = score {
            if best.map_or(true, |(_, b)| s < b) {
                best = Some((opt, s));
            }
        }
    }
    best.map(|(o, _)| (*o).to_string())
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur: Vec<usize> = vec![0; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

/// Option candidates visible for suggestions at each scope.  These include
/// hidden options that the upstream accepts.
fn suggestion_options(scope: UsageScope) -> &'static [&'static str] {
    match scope {
        UsageScope::Root => &["--verbose", "--output-format", "--help", "--version"],
        UsageScope::Build => &[
            "--verbose",
            "--output-format",
            "--json-only",
            "--project-root",
            "--config-path",
            "--help",
        ],
        UsageScope::Dev => &[
            "--verbose",
            "--output-format",
            "--port",
            "--no-first-build",
            "--include-paths",
            "--project-root",
            "--config-path",
            "--help",
        ],
        UsageScope::Serve => &["--verbose", "--output-format", "--port", "--help"],
        UsageScope::Generate => &[
            "--verbose",
            "--output-format",
            "--output-path",
            "--site-path",
            "--help",
        ],
        UsageScope::GenerateCi => &[
            "--verbose",
            "--output-format",
            "--output-path",
            "--site-path",
            "--ci",
            "--help",
        ],
    }
}

struct GlobalState {
    globals: Globals,
    verbose_seen: bool,
    format_seen: bool,
}

impl GlobalState {
    fn new() -> Self {
        Self {
            globals: Globals::default(),
            verbose_seen: false,
            format_seen: false,
        }
    }

    fn set_verbose(&mut self, scope: UsageScope, bin: &str) -> Result<(), CliError> {
        if self.verbose_seen {
            return Err(err_duplicate("--verbose", scope, bin));
        }
        self.verbose_seen = true;
        self.globals.verbose = true;
        Ok(())
    }

    fn set_output_format(
        &mut self,
        v: &str,
        scope: UsageScope,
        bin: &str,
    ) -> Result<(), CliError> {
        if self.format_seen {
            return Err(err_duplicate(
                "--output-format <OUTPUT_FORMAT>",
                scope,
                bin,
            ));
        }
        self.format_seen = true;
        match OutputFormat::parse(v) {
            Some(fmt) => {
                self.globals.output_format = fmt;
                Ok(())
            }
            None => Err(err_invalid_value(
                "--output-format <OUTPUT_FORMAT>",
                v,
                Some("human, json"),
                None,
            )),
        }
    }
}

pub fn parse(bin: &str, args: &[String]) -> Result<Action, CliError> {
    let mut state = GlobalState::new();
    let mut i = 0;
    while i < args.len() {
        let raw = args[i].as_str();
        match raw {
            "-h" => return Ok(Action::PrintStdout(help::main_short(bin))),
            "--help" => return Ok(Action::PrintStdout(help::main_long(bin))),
            "-V" | "--version" => return Ok(Action::PrintStdout(String::from("oranda 0.6.5\n"))),
            "-v" | "--verbose" => {
                state.set_verbose(UsageScope::Root, bin)?;
                i += 1;
            }
            "--output-format" => {
                let Some(v) = args.get(i + 1) else {
                    return Err(err_missing_value(
                        "--output-format <OUTPUT_FORMAT>",
                        Some("human, json"),
                    ));
                };
                state.set_output_format(v, UsageScope::Root, bin)?;
                i += 2;
            }
            s if s.starts_with("--output-format=") => {
                let v = &s["--output-format=".len()..];
                state.set_output_format(v, UsageScope::Root, bin)?;
                i += 1;
            }
            "build" => return parse_build(bin, &args[i + 1..], state),
            "dev" => return parse_dev(bin, &args[i + 1..], state),
            "serve" => return parse_serve(bin, &args[i + 1..], state),
            "generate" => return parse_generate(bin, &args[i + 1..], state),
            "help" => return parse_help(bin, &args[i + 1..]),
            sub if !sub.starts_with('-') => {
                return Err(err_unknown_subcommand(bin, sub, UsageScope::Root));
            }
            other => {
                let tip = suggest_similar(other, suggestion_options(UsageScope::Root))
                    .map(|s| format!("a similar argument exists: '{}'", s));
                return Err(err_unknown_argument(bin, other, UsageScope::Root, tip));
            }
        }
    }
    Ok(Action::PrintStdout(help::main_short(bin)))
}

