use std::process::ExitCode;

use crate::cli::Globals;
use crate::commands::DevArgs;
use crate::messages;

pub fn run(_globals: Globals, args: DevArgs) -> Result<(), ExitCode> {
    let mut count = 0usize;
    if std::path::Path::new("README.md").exists() {
        count += 1;
    }
    if std::path::Path::new("oranda.json").exists() {
        count += 1;
    }
    for p in &args.include_paths {
        if std::path::Path::new(p).exists() {
            count += 1;
        }
    }
    messages::info(&format!("Found {} paths to watch, starting watch...", count));

    let port = args.port.unwrap_or(7979);

    let dist_dir = "public";
    messages::success(&format!(
        "Your project is available at: http://127.0.0.1:{}",
        port
    ));

    if !std::path::Path::new(dist_dir).is_dir() {
        // Mimic the upstream panic: print the message, but keep the
        // server-like process running so the timeout in user code
        // determines the actual exit.
        eprintln!("  × oranda panicked.");
        eprintln!("  ├─▶ at src/commands/dev.rs:131:62");
        eprintln!("  ╰─▶ called `Result::unwrap()` on an `Err` value: BuildNotFound {{ dist_dir: \"public\" }}");
        eprintln!("  help: set the `RUST_BACKTRACE=1` environment variable to display a backtrace.");
        eprintln!();
        // Block forever (will be killed by Ctrl-C or timeout).
        loop {
            std::thread::park();
